Definition re_ivs : list (Z * Z) :=
  [(0x10000,0x113a10); (0x113a11,0x113a59); (0x123a59,0x123c50); (0x123d38,0x143d48); (0x123c84,0x123cd0); (0x123cd8,0x123cf0);
